<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Plus, Wallet, Search } from '@lucide/vue'
import { api, list, money, today } from '../api'
import type { Expense } from '../types'
import AppModal from '../components/AppModal.vue'
const rows=ref<Expense[]>([]), error=ref(''), formError=ref(''), open=ref(false), busy=ref(false), query=ref(''), key=ref(crypto.randomUUID()), submitted=ref<string>()
const form=reactive({category:'Kommunal',purpose:'',recipient:'',amount:'',payment_method:'cash',date:today()})
const filtered=computed(()=>rows.value.filter(r=>`${r.purpose} ${r.category} ${r.recipient}`.toLocaleLowerCase().includes(query.value.toLocaleLowerCase())))
const sum=computed(()=>rows.value.reduce((s,r)=>s+Number(r.amount),0))
async function load(){try{rows.value=await list<Expense>('expenses/')}catch(e){error.value=(e as Error).message}}
onMounted(load)
function start(){open.value=true;formError.value=''; if(!submitted.value){key.value=crypto.randomUUID();Object.assign(form,{category:'Kommunal',purpose:'',recipient:'',amount:'',payment_method:'cash',date:today()})}}
async function save(){busy.value=true;formError.value='';try{submitted.value ||= JSON.stringify({...form,key:key.value});await api('expenses/',{method:'POST',body:submitted.value});submitted.value=undefined;open.value=false;await load()}catch(e){formError.value=(e as Error).message;if((e as {status?:number}).status===400)submitted.value=undefined}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><span class="eyebrow">MOLIYAVIY TARTIB</span><h1>Xarajatlar<span class="heading-dot">.</span></h1><p>Nimaga, kimga va qancha — har bir chiqim ochiq.</p></div><button class="button primary" @click="start"><Plus :size="18"/>Xarajat kiritish</button></div><div class="expense-summary"><span class="metric-icon orange"><Wallet :size="22"/></span><div><span class="muted">Barcha kiritilgan xarajatlar</span><h2>{{ money(sum) }} <small>so‘m</small></h2></div><span class="pill">{{ rows.length }} ta yozuv</span></div><p v-if="error" class="alert error">{{ error }}</p><section class="panel"><header class="panel-heading"><div><h2>Xarajatlar ro‘yxati</h2><p>Admin saqlashi bilan hisobga olinadi</p></div><div class="search-field"><Search :size="17"/><input v-model="query" placeholder="Maqsad, oluvchi, kategoriya…" aria-label="Xarajat qidirish"></div></header><div class="table-wrap"><table><thead><tr><th>MAQSAD / OLUVCHI</th><th>KATEGORIYA</th><th>SANA</th><th>SUMMA</th><th>TO‘LOV</th><th>KIRITGAN</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td><strong>{{ row.purpose }}</strong><small>{{ row.recipient || 'Oluvchi ko‘rsatilmagan' }}</small></td><td><span class="pill subtle">{{ row.category }}</span></td><td>{{ row.date }}</td><td class="number">{{ money(row.amount) }}</td><td><span class="status" :class="row.payment_method==='unpaid'?'open':'paid'">{{ row.payment_method==='cash'?'Naqd':row.payment_method==='card'?'Karta':'To‘lanmagan' }}</span></td><td>{{ row.actor_name }}</td></tr></tbody></table><div v-if="!filtered.length" class="empty-state"><Wallet :size="38" :stroke-width="1.3"/><h3>Xarajatlar hali yo‘q</h3><p>Ijara, kommunal va boshqa kundalik xarajatlarni kiriting.</p></div></div></section><p class="data-note">Bu bo‘lim kundalik xarajatlar uchun. Ombor xaridi qiymati va ikkiyoqlama buxgalteriya registri hali ulanmagan.</p><AppModal :open="open" title="Yangi xarajat" @close="!busy&&(open=false)"><form @submit.prevent="save"><fieldset :disabled="!!submitted||busy"><div class="form-row"><label>Kategoriya<select v-model="form.category"><option>Kommunal</option><option>Ijara</option><option>Transport</option><option>Ta’mirlash</option><option>Tozalash</option><option>Boshqa</option></select></label><label>Sana<input v-model="form.date" type="date" :max="today()" required></label></div><label>Nimaga ishlatildi?<textarea v-model="form.purpose" required maxlength="250" rows="2" placeholder="Masalan, sentabr oyi elektr to‘lovi"/></label><label>Kimga to‘landi?<input v-model="form.recipient" maxlength="120" placeholder="Tashkilot yoki shaxs"></label><div class="form-row"><label>Summa, so‘m<input v-model="form.amount" type="number" min="1" step="0.01" required></label><label>To‘lov<select v-model="form.payment_method"><option value="cash">Naqd to‘landi</option><option value="card">Karta to‘landi</option><option value="unpaid">Hali to‘lanmagan</option></select></label></div></fieldset><p class="alert">Saqlangach darhol hisobga olinadi. Superadmin tasdig‘i talab qilinmaydi.</p><p v-if="formError" class="alert error">{{ formError }}</p><button class="button primary full" :disabled="busy">{{ busy?'Saqlanmoqda…':submitted?'Oldingi amalni qayta tekshirish':'Xarajatni saqlash' }}</button></form></AppModal></template>
